#[cfg(test)]
mod tests {
    use super::*;
    use crate::humanoid::detect_humanoid_profile;
    use crate::skeleton_asset::{compute_skeleton_identity, BoneDef};
    use engine_authoring::id::AssetId;

    #[test]
    fn imported_humanoid_motion_cache_key_tracks_source_and_provenance() {
        let motion = AssetId::generate();
        let source_a = AssetId::generate();
        let source_b = AssetId::generate();

        let first = imported_humanoid_motion_cache_key(&motion, "fingerprint-a", Some(&source_a));
        let changed_source =
            imported_humanoid_motion_cache_key(&motion, "fingerprint-a", Some(&source_b));
        let changed_bytes =
            imported_humanoid_motion_cache_key(&motion, "fingerprint-b", Some(&source_a));
        let model_contained =
            imported_humanoid_motion_cache_key(&motion, "fingerprint-a", None);

        assert_ne!(first, changed_source);
        assert_ne!(first, changed_bytes);
        assert_ne!(first, model_contained);
    }

